import csv, math
rows=list(csv.reader(open('/data/reader/PL1.csv')))
data={r[0]:float(r[1]) for r in rows[1:]}
stds=[]
for col in [1,2]:
    for r,nom in zip('ABCDEFGH',[0,125,250,500,750,1000,1500,2000]):
        stds.append((nom,data[f'{r}{col}']))
def fit_quad(x,y):
    n=len(x); S0=n; S1=sum(x); S2=sum(xi*xi for xi in x); S3=sum(xi**3 for xi in x); S4=sum(xi**4 for xi in x)
    T0=sum(y); T1=sum(xi*yi for xi,yi in zip(x,y)); T2=sum(xi*xi*yi for xi,yi in zip(x,y))
    M=[[S0,S1,S2],[S1,S2,S3],[S2,S3,S4]]; b=[T0,T1,T2]
    n=len(M)
    for i in range(n):
        p=i
        for j in range(i+1,n):
            if abs(M[j][i])>abs(M[p][i]): p=j
        M[i],M[p]=M[p],M[i]; b[i],b[p]=b[p],b[i]
        piv=M[i][i]
        for j in range(i,n): M[i][j]/=piv
        b[i]/=piv
        for r in range(n):
            if r!=i:
                fac=M[r][i]
                for j in range(i,n): M[r][j]-=fac*M[i][j]
                b[r]-=fac*b[i]
    return b[2],b[1],b[0] # a,b,c
def conc_from(yval,coef):
    a,b,c=coef; C=c-yval; disc=b*b-4*a*C
    return (-b+math.sqrt(disc))/(2*a)
for factor in [1.0,1.2,1.25,1.26,1.27,1.28,1.3]:
    x=[nom*factor for nom,_ in stds]; y=[v for _,v in stds]
    coef=fit_quad(x,y)
    cls=[conc_from(data[w],coef) for w in ['A3','B3','C3','D3']]
    chs=[conc_from(data[w],coef) for w in ['E3','F3','G3','H3']]
    print('factor',factor,'L avg',sum(cls)/4,'H avg',sum(chs)/4)
